        n = start + 1
    vars[key] = n
    if f is None:
        instr = 'Unknown product. Use a product_id from ACCOUNT and call note_refusal again.'
        state = 'unknown'
    else:
        allowed = int(f.get('attempts') or 1)
        if n > allowed:
            state = 'exhausted'
            instr = ('Attempts used up for ' + f['label'] + ' (' + str(allowed) + ' allowed). Do NOT propose anything more. '
