import json
PROMISE_OUTCOME = 'promise'
XFER_OUTCOME = 'transferred'
XFER_REASON = {'support': 'support', 'restructuring': 'restructuring', 'general': 'human'}
PAID_OUTCOME = 'paid'
NO_PROMISE_OUTCOME = 'no_promise'
MULTI = True
REASON_PRIORITY = []
PROMISE_FAREWELL = 'Your promise is recorded. Your promise is noted. A reminder will be sent the day before the payment date. Thank you for your time, NAME. Goodbye.'
NAME_TOKEN = 'NAME'
FAREWELLS = {'paid': 'Thank you for letting me know. Payments take up to two business days to show. Thank you for your time, NAME. Goodbye.', 'no_promise': 'I understand. Thank you for your time, NAME. Goodbye.', 'no_promise_hardship': 'Thank you for your time, NAME. Goodbye.', 'no_promise_dispute': 'I understand. Thank you for your time, NAME. Goodbye.', 'no_promise_service_error': 'I am sorry, I could not record your promise because of a technical problem. Thank you for your time, NAME. Goodbye.', 'xfer_support': 'I am connecting you with our support team now. Thank you for your time. Goodbye.', 'xfer_restructuring': 'I am connecting you with the team that handles payment plans now. Thank you for your time. Goodbye.', 'xfer_general': 'I am connecting you with a colleague now. Thank you for your time. Goodbye.'}
import json
try:
    outcome = str(vars.get('hint_outcome') or NO_PROMISE_OUTCOME)
    reason = str(vars.get('hint_reason') or '')
    farewell = str(vars.get('hint_farewell') or 'Thank you for your time. Goodbye.')
    try:
        promises = json.loads(str(vars.get('promises_json') or '[]'))
    except Exception:
        promises = []
    try:
        notes = json.loads(str(vars.get('notes_json') or '[]'))
    except Exception:
        notes = []
    try:
        pc = int(vars.get('create_promise_success_count') or 0)
    except Exception:
        pc = 0
    if pc > len(promises):
        promises = promises + [dict(pid='?')] * (pc - len(promises))
    q = str(vars.get('transfer_queue') or '')
    if q:
        outcome = XFER_OUTCOME
        reason = XFER_REASON.get(q, q)
        farewell = FAREWELLS.get('xfer_' + q) or farewell
    elif promises:
        outcome = PROMISE_OUTCOME
        reason = ''
        farewell = PROMISE_FAREWELL
    elif MULTI and notes:
        if all(str(n.get('reason')) == 'paid' for n in notes):
            outcome = PAID_OUTCOME
            reason = ''
            farewell = FAREWELLS.get('paid') or farewell
        else:
            first = ''
            reasons = [str(n.get('reason')) for n in notes if str(n.get('reason')) != 'paid']
            for r in REASON_PRIORITY:
                if r in reasons:
                    first = r
                    break
            if not first and reasons:
                first = reasons[0]
            outcome = NO_PROMISE_OUTCOME
            reason = first
            farewell = FAREWELLS.get('no_promise_' + first) or FAREWELLS.get('no_promise') or farewell
    name = (str(vars.get('title') or '') + ' ' + str(vars.get('last_name') or '')).strip()
    vars['outcome'] = outcome
    vars['reason'] = reason
    vars['outcome_decided'] = 'true'
    vars['farewell'] = farewell.replace(NAME_TOKEN, name) if name else farewell.replace(', ' + NAME_TOKEN, '').replace(NAME_TOKEN, '')
except Exception:
    try:
        vars['outcome'] = str(vars.get('hint_outcome') or NO_PROMISE_OUTCOME)
        vars['reason'] = str(vars.get('hint_reason') or '')
        vars['farewell'] = 'Thank you for your time. Goodbye.'
    except Exception:
        pass

